import React, { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { api } from "../lib/api";

export default function Directory() {
  const [params] = useSearchParams();
  const [users, setUsers] = useState([]);
  const [q, setQ] = useState("");
  const [role, setRole] = useState(params.get("role") || "");
  const [industry, setIndustry] = useState("");
  const load = async () => {
    const sp = new URLSearchParams();
    if (role) sp.set("role", role);
    if (industry) sp.set("industry", industry);
    if (q) sp.set("search", q);
    const { data } = await api.get(`/users?${sp}`);
    setUsers(data);
  };
  useEffect(() => { load(); /* eslint-disable-next-line */ }, [role, industry]);
  return (
    <div style={{ maxWidth: 1200, margin: "0 auto", padding: "3rem 2rem" }}>
      <div className="overline">The Directory</div>
      <h1 className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)", margin: "8px 0 2rem" }}>Every face in the network.</h1>
      <div className="card-editorial" style={{ padding: 20, marginBottom: 32, display: "grid", gridTemplateColumns: "2fr 1fr 1fr auto", gap: 12 }}>
        <input className="input" placeholder="Search name, skill, bio…" value={q} onChange={e => setQ(e.target.value)} onKeyDown={e => e.key === "Enter" && load()} />
        <select className="input" value={role} onChange={e => setRole(e.target.value)}>
          <option value="">All Roles</option><option value="student">Students</option><option value="alumni">Alumni</option>
        </select>
        <input className="input" placeholder="Industry" value={industry} onChange={e => setIndustry(e.target.value)} />
        <button className="btn-primary" onClick={load}>Apply</button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 16 }}>
        {users.map(u => (
          <Link key={u.id} to={`/profile/${u.id}`} className="card-editorial" style={{ padding: 24, textDecoration: "none" }}>
            <div className="overline">{u.role} {u.graduation_year && `· ${u.graduation_year}`}</div>
            <div className="font-serif" style={{ fontSize: 22, color: "var(--ivy)", margin: "4px 0 8px" }}>{u.name}</div>
            <div style={{ color: "var(--muted)", fontSize: 14, marginBottom: 8 }}>{u.industry}</div>
            <div style={{ color: "var(--muted)", fontSize: 13, lineHeight: 1.5 }}>{u.bio}</div>
            <div style={{ marginTop: 12, display: "flex", gap: 6, flexWrap: "wrap" }}>
              {(u.skills || []).slice(0, 3).map(s => <span key={s} className="tag">{s}</span>)}
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}
